import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the last day of the month for a given date.
 * @param {string} dateStr - Date in YYYY-MM-DD format
 * @returns {string} Last day of the month in YYYY-MM-DD format
 */
function lastDayOfMonth(dateStr) {
  const [year, month] = dateStr.split('-');
  const nextMonth = String(parseInt(month) + 1).padStart(2, '0');
  const nextMonthFirstDay = `${year}-${nextMonth}-01`;
  return addDays(nextMonthFirstDay, -1);
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @param {string} terms - Payment terms: 'NET14', 'NET30', or 'EOM'
 * @returns {string} Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    return lastDayOfMonth(issueDate);
  }
  return null;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date based on terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discountPercent: line's own, or customer tier default
    let discountPercent;
    if (line.discountPercent !== undefined) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single invoice line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents(total * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT for a single invoice line (on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number} VAT in cents
 */
export function lineVat(line) {
  const vatRate = line.vatRate ?? 0;
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const afterDiscount = total - discount;
  const vat = roundCents(afterDiscount * vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate the subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher: Math.max(0, voucher),
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<any>, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param1
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent
  const finalDiscountPercent = discountPercent ?? 0;
  if (typeof finalDiscountPercent !== 'number' || finalDiscountPercent < 0 || finalDiscountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with same SKU
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Increase qty of existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscountPercent,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }>, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new lines array without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice (assign a number and change status to issued).
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already issued
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: any, lines: Array<any> }} invoice
 * @param {{ code: string, amount: number }} param1
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status: must be draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount: must be a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

